"""Meeting room booking calendar.

Bookings are half-open intervals [start, end) in a room's local minutes
since midnight, so back-to-back bookings (one ending exactly when the
next starts) never conflict.
"""

from __future__ import annotations


def make_calendar() -> dict:
    """{room_id: [{"booking_id", "start", "end"}, ...]}"""
    return {}


def book_room(calendar: dict, room_id: str, start: int, end: int, booking_id: str) -> None:
    """Add a booking for `room_id` unconditionally (no conflict check)."""
    calendar.setdefault(room_id, []).append(
        {"booking_id": booking_id, "start": start, "end": end},
    )


def bookings_for_room(calendar: dict, room_id: str) -> list[dict]:
    """All bookings currently on `room_id`'s calendar."""
    return list(calendar.get(room_id, []))


def cancel_booking(calendar: dict, booking_id: str) -> None:
    """Remove a booking by id from whichever room it's on."""
    for bookings in calendar.values():
        for b in list(bookings):
            if b["booking_id"] == booking_id:
                bookings.remove(b)
                return
